<?php require '../config.php';$gameId=(int)($_GET['game']??0);$token=$_GET['token']??'';$s=db()->prepare('SELECT g.*,q.title,(SELECT COUNT(*) FROM questions WHERE quiz_id=g.quiz_id) total_questions FROM games g JOIN quizzes q ON q.id=g.quiz_id WHERE g.id=?');$s->bind_param('i',$gameId);$s->execute();$g=$s->get_result()->fetch_assoc();if(!$g)json_response(['error'=>'Not found'],404);$data=['status'=>$g['status'],'code'=>$g['code'],'title'=>$g['title'],'current'=>(int)$g['current_question'],'total'=>(int)$g['total_questions'],'music'=>$g['music_theme']];
$players=db()->query('SELECT name,avatar,score FROM players WHERE game_id='.$gameId.' ORDER BY score DESC,joined_at ASC')->fetch_all(MYSQLI_ASSOC);$data['players']=$players;
if($g['status']==='question'||$g['status']==='results'){$s=db()->prepare('SELECT * FROM questions WHERE quiz_id=? ORDER BY position LIMIT ?,1');$idx=max(0,(int)$g['current_question']-1);$s->bind_param('ii',$g['quiz_id'],$idx);$s->execute();$q=$s->get_result()->fetch_assoc();if($q){$answers=db()->query('SELECT id,text'.($g['status']==='results'?',is_correct':'').' FROM answers WHERE question_id='.(int)$q['id'].' ORDER BY position')->fetch_all(MYSQLI_ASSOC);$elapsed=$g['question_started_at']?(int)((microtime(true)-strtotime($g['question_started_at']))*1000):0;$count=(int)db()->query('SELECT COUNT(*) c FROM responses WHERE game_id='.$gameId.' AND question_id='.(int)$q['id'])->fetch_assoc()['c'];$data['question']=['id'=>$q['id'],'text'=>$q['text'],'type'=>$q['type'],'time'=>(int)$q['time_limit'],'media_path'=>$q['media_path'],'media_type'=>$q['media_type'],'answers'=>$answers,'elapsed_ms'=>max(0,$elapsed),'responses'=>$count];}}
if($token){$s=db()->prepare('SELECT id,score FROM players WHERE token=? AND game_id=?');$s->bind_param('si',$token,$gameId);$s->execute();$p=$s->get_result()->fetch_assoc();if(!$p)json_response(['error'=>'Unauthorized'],403);$data['me']=$p;if(isset($data['question'])){$s=db()->prepare('SELECT is_correct,points_awarded FROM responses WHERE player_id=? AND question_id=?');$s->bind_param('ii',$p['id'],$data['question']['id']);$s->execute();$data['response']=$s->get_result()->fetch_assoc();}}
json_response($data);

